package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.world.phys.Vec3;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class GeraniumPlatformLayoutTest {
 @Test void thirtyUniquePartsAndOneAnchorInEachDirection(){for(Direction d:new Direction[]{Direction.SOUTH,Direction.WEST,Direction.NORTH,Direction.EAST}){var root=new BlockPos(-18,80,47);var positions=new HashSet<BlockPos>();for(int i=0;i<GeraniumPlatformLayout.PARTS;i++){var p=GeraniumPlatformLayout.cell(root,d,i);assertTrue(positions.add(p));assertEquals(root,GeraniumPlatformLayout.anchor(p,d,i));assertEquals(i<15?80:81,p.getY());}assertEquals(30,positions.size());}}
 @Test void originalBBSizedGeometryNeedsNoLucasScale(){assertEquals(1,GeraniumPlatformLayout.FIT_SCALE);var p=GeraniumPlatformLayout.fitPoint(new Vec3(0,0,-16));var origin=GeraniumPlatformLayout.fitPoint(Vec3.ZERO);var delta=p.subtract(origin);assertEquals(1,delta.length(),1e-9);assertEquals(Math.tan(Math.toRadians(14)),delta.y/delta.horizontalDistance(),1e-9);assertTrue(delta.z>0);assertEquals(1.3675739315689992,origin.y,1e-8);assertEquals(-0.06048047389991693,origin.z,1e-8);}
 @Test void clipsUseTheirOwnDurationsAndLidOffsetIsAddedOnce(){assertEquals(15,GeraniumPlatformClampAnimation.TICKS);assertEquals(14,GeraniumPlatformClampAnimation.LID_TICKS);assertEquals(Math.toRadians(38),GeraniumPlatformClampAnimation.LEFT_RADIANS,1e-6);assertEquals(-GeraniumPlatformClampAnimation.LEFT_RADIANS,GeraniumPlatformClampAnimation.RIGHT_RADIANS,1e-6);assertEquals(0,GeraniumPlatformClampAnimation.LID_BASE_X+GeraniumPlatformClampAnimation.LID_CLOSE_X,1e-6);}
 @Test void allSelectionWalksStayBoundedAndCollisionStaysWithinItsCellMargin(){long start=System.nanoTime();int total=0;for(Direction d:new Direction[]{Direction.SOUTH,Direction.WEST,Direction.NORTH,Direction.EAST})for(int p=0;p<30;p++){var shape=GeraniumPlatformShapes.selection(d,p);int[] edges={0};shape.forAllEdges((a,b,c,x,y,z)->edges[0]++);assertTrue(edges[0]<=12,d+":"+p+" edges="+edges[0]);total+=edges[0];var collision=GeraniumPlatformShapes.collision(d,p);if(!collision.isEmpty()){var b=collision.bounds();assertTrue(b.minX>=-.126 && b.minZ>=-.126 && b.minY>=0 && b.maxX<=1.126 && b.maxZ<=1.126 && b.maxY<=1);}}System.out.println("LP02_SHAPES 120 cached selections edges="+total+" including first cache initialization ms="+(System.nanoTime()-start)/1e6);}
}